window.MOTIF_CATALOG_CHUNKS[135]={"cards":[{"id":"ML-F11","row_version":1,"title":"동기·심리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"행동을 일으키는 욕구와 심리의 작동을 구분한다. 같은 행동이라도 동기에 따라 의미가 달라질 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/ML-F11/index.html"},{"id":"ML-F12","row_version":1,"title":"존재·종족","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"인간·동물·신·괴물·인공 생명 등 존재의 종류와 기원을 구분한다. 종족 자체에 선악이나 역할을 고정하지 않는다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/ML-F12/index.html"},{"id":"ML-F13","row_version":2,"title":"세계관·규칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"세계에서 가능한 일과 그 일이 성립하는 조건을 구분한다. 시간·생사·인과·힘의 체계와 비용을 포함한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/ML-F13/index.html"},{"id":"ML-F14","row_version":1,"title":"시공간·환경","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"이야기가 놓인 시대·장소·기후와 장면의 물리적 조건을 구분한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/ML-F14/index.html"},{"id":"ML-F15","row_version":1,"title":"사회·문화·생활","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"사회가 조직되고 일상이 유지되는 방식을 구분한다. 정치·경제·법·의례·돌봄·놀이를 포함한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/ML-F15/index.html"},{"id":"ML-F16","row_version":1,"title":"사물·도구·자원","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"작품에 등장하는 물건과 물질의 종류를 구분한다. 사물 자체의 종류와 상징적 사용은 별도로 연결한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/ML-F16/index.html"},{"id":"ML-F17","row_version":2,"title":"능력·기술·초자연","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"힘과 기술이 작동하는 방식, 발동 조건과 한계를 구분한다. 초능력·마법뿐 아니라 정보·생체 기술도 포함한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/ML-F17/index.html"},{"id":"ML-F18","row_version":1,"title":"주제·가치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"이야기가 제기하는 의미와 질문을 구분한다. 인물의 목표나 사건 자체와 구별해 읽는다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/ML-F18/index.html"},{"id":"ML-F19","row_version":3,"title":"정서·톤","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"작품이 불러일으키는 감정과 전반적인 분위기를 구분한다. 특정 장면의 정서와 작품 전체의 톤은 다를 수 있다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/ML-F19/index.html"},{"id":"ML-F20","row_version":1,"title":"상징·이미지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"반복되는 이미지가 맥락 안에서 수행하는 상징적 용법을 구분한다. 동일한 이미지의 의미를 하나로 고정하지 않는다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/ML-F20/index.html"},{"id":"ML-F21","row_version":1,"title":"미학·스타일","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"표현 방식과 조형적 취향을 구분한다. 장르·소재와 별도로 화면이나 문체가 어떤 인상을 만드는지 살핀다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/ML-F21/index.html"},{"id":"ML-F22","row_version":1,"title":"시각·공간 연출","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"공간·의상·조명·배치와 촬영·편집·그래픽을 통해 의미를 만드는 방식을 구분한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/ML-F22/index.html"},{"id":"ML-F23","row_version":2,"title":"서술·언어·정보","original":"Dialogue","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"누가 말하고 무엇을 어떤 순서와 말투로 알려주는지 구분한다. 시점·정보 차이·대사·언어유희를 포함한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/ML-F23/index.html"},{"id":"ML-F24","row_version":2,"title":"소리·음악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"소리·음악·목소리의 구성과 표현 기능을 구분한다. 작품의 매체가 음악이라는 사실과 음향 장치의 사용을 구별한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/ML-F24/index.html"},{"id":"ML-F25","row_version":3,"title":"게임·상호작용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"이용자의 행위와 그 결과를 정하는 규칙을 구분한다. 조작·탐색·성장·선택·보상과 서사의 연결을 포함한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/ML-F25/index.html"},{"id":"ML-F26","row_version":2,"title":"공연·참여·팬덤","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"무대의 수행 방식과 관객·팬의 참여를 구분한다. 특정 산업에 한정하지 않고 공연과 공동 감상의 관습을 살핀다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/ML-F26/index.html"},{"id":"ML-F27","row_version":2,"title":"메타·제작·유통","original":"Creator Speak","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"작품의 자기반영과 제작·각색·유통·수용 관행을 구분한다. 작품 안의 설정과 작품 밖의 제작 조건을 구별한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/ML-F27/index.html"},{"id":"ML-F28","row_version":1,"title":"변주·관습","original":"Universal","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"익숙한 요소를 정석대로 사용하거나 결합·반전·해체하는 방식을 구분한다. 평가는 구체적인 사용 맥락과 함께 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/ML-F28/index.html"},{"id":"ML-F29","row_version":2,"title":"기원·전승·참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"모티프가 참조하는 자료와 전승의 계보를 구분한다. 작품의 배경 지역과 모티프의 기원을 같은 것으로 보지 않는다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/ML-F29/index.html"},{"id":"ML-F30","row_version":2,"title":"대상·수용맥락","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"facet","parent_id":null,"tag_path":[],"summary":"대상층·이용 목적·감상 환경과 독해 조건을 구분한다. 개념 자체보다 작품이나 사례에 적용하는 경우가 많다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/ML-F30/index.html"}]}.cards;